<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Clientes</title><style>body{font-family:Arial;max-width:800px;margin:30px auto;background:#f0f0f0}div{background:white;padding:20px;border-radius:8px}h1{color:#FF9900}input{width:100%;padding:8px;margin:5px 0;border:1px solid #ccc;border-radius:4px}button{width:100%;padding:10px;background:#FF9900;color:white;border:none;border-radius:4px;cursor:pointer;margin:10px 0}table{width:100%;border-collapse:collapse}th,td{padding:8px;border:1px solid #ddd;text-align:left}th{background:#232F3E;color:white}tr:hover{background:#f5f5f5}.info{background:#e7f3ff;border-left:4px solid #0066cc;padding:10px;margin-bottom:15px}.msg{padding:10px;margin:10px 0;border-radius:4px}.ok{background:#d4edda;color:#155724}.err{background:#f8d7da;color:#721c24}</style></head><body><div><h1>📋 Cadastro de Clientes AWS</h1><div class="info"><p><strong>Instância:</strong> INSTANCE_ID_PLACEHOLDER</p><p><strong>IP:</strong> PRIVATE_IP_PLACEHOLDER | <strong>AZ:</strong> AVAILABILITY_ZONE_PLACEHOLDER</p></div><?php $db="DB_HOST_PLACEHOLDER";$u="DB_USER_PLACEHOLDER";$p="DB_PASS_PLACEHOLDER";if($_POST){$c=@new mysqli($db,$u,$p,"cadastro_db");if(!$c->connect_error){$n=$c->real_escape_string($_POST['nome']);$s=$c->real_escape_string($_POST['sobrenome']);$i=(int)$_POST['idade'];$pa=$c->real_escape_string($_POST['pais']);$t=$c->real_escape_string($_POST['telefone']);if($c->query("INSERT INTO clientes(nome,sobrenome,idade,pais,telefone)VALUES('$n','$s',$i,'$pa','$t')")===TRUE)echo "<div class='msg ok'>✅ $n $s cadastrado!</div>";else echo "<div class='msg err'>❌ Erro: ".$c->error."</div>";$c->close();}else echo "<div class='msg err'>❌ Erro BD: ".$c->connect_error."</div>";}?><form method="POST"><input name="nome" placeholder="Nome" required><input name="sobrenome" placeholder="Sobrenome" required><input type="number" name="idade" placeholder="Idade" min="1" required><input name="pais" placeholder="País" required><input name="telefone" placeholder="Telefone" required><button type="submit">💾 Salvar</button></form><?php $c=@new mysqli($db,$u,$p,"cadastro_db");if(!$c->connect_error){$r=$c->query("SELECT * FROM clientes ORDER BY id DESC");if($r&&$r->num_rows>0){echo "<h3>Clientes (".$r->num_rows.")</h3><table><tr><th>ID</th><th>Nome</th><th>Sobrenome</th><th>Idade</th><th>País</th><th>Telefone</th><th>Data</th></tr>";while($row=$r->fetch_assoc()){$d=date('d/m/Y H:i',strtotime($row['data_criacao']));echo "<tr><td>#".$row['id']."</td><td>".htmlspecialchars($row['nome'])."</td><td>".htmlspecialchars($row['sobrenome'])."</td><td>".$row['idade']."</td><td>".htmlspecialchars($row['pais'])."</td><td>".htmlspecialchars($row['telefone'])."</td><td>$d</td></tr>";}echo "</table>";}else echo "<p style='text-align:center;color:#999'>Nenhum cliente cadastrado</p>";$c->close();}else{echo "<p class='msg err'>❌ Erro ao conectar para listar clientes: ".$c->connect_error."</p>";}$c=null;?></div></body></html>
